  "userQuery": "帮我做个睡眠卡片连手环，自动生成昨晚睡眠报告，打分，低于60分给改善建议。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.health",
        "abilityName": "com.huawei.health.MainAbility",
        "uri": "health://sleep/detail"
      }
    }
  ],
  "dataModel": {
    "value": {
      "sleep": {
        "title": "昨晚睡眠",
        "scoreText": "56分",
        "scoreValue": 56,
        "reportText": "深睡偏少",
        "adviceText": "建议今晚提前30分钟入睡",
        "actionText": "查看详情"
      }
    }
  },
  "assetCandidates": []
}

